import SwiftUI
import AVFoundation
import AppKit
import QuartzCore

struct EditorPlaybackResource {
    let chart: SimaiChart?
    let musicURL: URL
    let duration: TimeInterval
}

@MainActor
final class EditorPlaybackClock: ObservableObject {
    @Published fileprivate(set) var currentTime: TimeInterval = 0
}

struct EditorPlaybackTimeMapping {
    let hostTime: TimeInterval
    let presentationTime: TimeInterval
    let rate: Double
    let duration: TimeInterval

    func presentationTime(atSystemUptime timestamp: TimeInterval) -> TimeInterval {
        let predicted = presentationTime + (timestamp - hostTime) * rate
        return max(0, min(predicted, duration))
    }
}

@MainActor
final class EditorChartPlayerModel: NSObject, ObservableObject, AVAudioPlayerDelegate {
    @Published private(set) var resource: EditorPlaybackResource?
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?
    @Published private(set) var isPlaying = false

    let clock = EditorPlaybackClock()

    private var player: AVAudioPlayer?
    private var displayLink: CADisplayLink?
    private var isScrubbing = false
    private var resumesPlaybackAfterScrubbing = false
    private var playbackVolume: Float = 1
    private var needsAudioPreparation = true
    private var audioPresentationLatency: TimeInterval = EditorChartPlayerModel.audioPlayerPipelineLatency
    private var playbackVisualFloor: TimeInterval?

    // Preserve the existing device calibration baseline while driving every
    // song from the same local audio-device clock. Route-reported latency can
    // be larger (for example, AirPlay), so the larger value still wins.
    private static let audioPlayerPipelineLatency: TimeInterval = 0.085
    private static let scheduledStartLeadTime: TimeInterval = 0.02

    var chart: SimaiChart? { resource?.chart }
    var duration: TimeInterval { resource?.duration ?? 1 }
    var currentTime: TimeInterval { clock.currentTime }
    var livePresentationTime: TimeInterval {
        playbackTimeMapping().presentationTime(
            atSystemUptime: ProcessInfo.processInfo.systemUptime
        )
    }
    var hitSoundClockTime: TimeInterval {
        guard let rawTime = rawPlaybackTime(
            atSystemUptime: ProcessInfo.processInfo.systemUptime
        ) else {
            return clock.currentTime + audioPresentationLatency
        }
        return max(0, min(rawTime, duration))
    }

    // Editor adapter: local media replaces LXNS fetching; clock/motion are upstream.
    func load(chart: SimaiChart?, musicURL: URL, duration: TimeInterval, volume: Double) throws {
        let position = currentTime
        if resource?.musicURL != musicURL {
            stop()
            try configurePlayer(url: musicURL, volume: volume)
        }
        resource = EditorPlaybackResource(chart: chart, musicURL: musicURL, duration: duration)
        setVolume(volume)
        seek(to: position)
    }

    func setVolume(_ value: Double) {
        playbackVolume = Float(max(0, min(value, 1)))
        player?.volume = playbackVolume
    }

    func togglePlayback() {
        isPlaying ? pause() : play()
    }

    func play() {
        guard resource != nil, !isPlaying else { return }
        if currentTime >= duration - 0.1 { seek(to: 0) }
        startPlayback()
    }

    private func startPlayback() {
        guard let resource else { return }
        errorMessage = nil
        let position = currentTime
        do {
            // Retry a stale player once, e.g. after the audio service was reset.
            for _ in 0...1 {
                if player == nil { player = try makePlayer(url: resource.musicURL) }
                guard let player else { break }
                if needsAudioPreparation {
                    player.currentTime = position
                    if !player.prepareToPlay() {
                        discardAudioPlayer()
                        continue
                    }
                }
                let startTime = player.deviceCurrentTime + Self.scheduledStartLeadTime
                if player.play(atTime: startTime) {
                    needsAudioPreparation = false
                    playbackVisualFloor = position
                    isPlaying = true
                    displayLink?.isPaused = false
                    return
                }
                discardAudioPlayer()
            }
            throw AVError(.unknown)
        } catch {
            suspendAudio()
            errorMessage = error.localizedDescription
        }
    }

    func suspendAudio() {
        pause()
        needsAudioPreparation = true
        resumesPlaybackAfterScrubbing = false
    }

    private func discardAudioPlayer() {
        player?.delegate = nil
        player = nil
        needsAudioPreparation = true
    }

    func pause() {
        player?.pause()
        isPlaying = false
        displayLink?.isPaused = true
        playbackVisualFloor = nil
    }

    func seek(to time: TimeInterval, precise: Bool = true) {
        _ = precise
        let clamped = max(0, min(time, duration))
        player?.currentTime = clamped
        clock.currentTime = clamped
        playbackVisualFloor = isPlaying ? clamped : nil
    }

    func scrub(to time: TimeInterval) {
        if !isScrubbing {
            isScrubbing = true
            resumesPlaybackAfterScrubbing = isPlaying
            player?.pause()
            isPlaying = false
            displayLink?.isPaused = true
        }

        clock.currentTime = max(0, min(time, duration))
    }

    func finishScrubbing(at time: TimeInterval) {
        if !isScrubbing {
            isScrubbing = true
            resumesPlaybackAfterScrubbing = isPlaying
            player?.pause()
            isPlaying = false
            displayLink?.isPaused = true
        }

        let clamped = max(0, min(time, duration))
        let shouldResume = resumesPlaybackAfterScrubbing
        clock.currentTime = clamped

        player?.currentTime = clamped
        isScrubbing = false
        resumesPlaybackAfterScrubbing = false
        if shouldResume { startPlayback() }
    }

    func stop() {
        isScrubbing = false
        resumesPlaybackAfterScrubbing = false
        player?.stop()
        player?.delegate = nil
        isPlaying = false
        displayLink?.isPaused = true
        clock.currentTime = 0
        resource = nil
        errorMessage = nil
        displayLink?.invalidate()
        displayLink = nil
        player = nil
        playbackVisualFloor = nil
        needsAudioPreparation = true

    }

    private func makePlayer(url: URL) throws -> AVAudioPlayer {
        let player = try AVAudioPlayer(contentsOf: url)
        player.delegate = self
        player.enableRate = true
        player.rate = 1
        player.volume = playbackVolume
        return player
    }

    private func configurePlayer(url: URL, volume: Double) throws {
        setVolume(volume)
        player = try makePlayer(url: url)
        needsAudioPreparation = true

        let selector = #selector(updatePlaybackTime(_:))
        guard let displayLink = NSApp.keyWindow?.displayLink(target: self, selector: selector)
            ?? NSScreen.main?.displayLink(target: self, selector: selector) else {
            throw CocoaError(.featureUnsupported)
        }
        displayLink.preferredFrameRateRange = CAFrameRateRange(minimum: 60, maximum: 60, preferred: 60)
        displayLink.isPaused = true
        displayLink.add(to: .main, forMode: .common)
        self.displayLink = displayLink
    }

    @objc private func updatePlaybackTime(_ displayLink: CADisplayLink) {
        guard !isScrubbing, isPlaying, player != nil else { return }
        // Render for the frame that is about to reach the display. The same
        // host-time mapping is used for touch judgement, so both stay on the
        // local audio-device timeline after changing songs or seeking.
        var presentationTime = playbackTimeMapping().presentationTime(
            atSystemUptime: displayLink.targetTimestamp
        )
        if let playbackVisualFloor {
            presentationTime = max(presentationTime, playbackVisualFloor)
            if presentationTime > playbackVisualFloor + 0.001 {
                self.playbackVisualFloor = nil
            }
        }
        clock.currentTime = presentationTime
    }

    func playbackTimeMapping() -> EditorPlaybackTimeMapping {
        let hostTime = ProcessInfo.processInfo.systemUptime
        let rawTime = rawPlaybackTime(atSystemUptime: hostTime)
            ?? min(clock.currentTime + audioPresentationLatency, duration)
        let effectiveRate = player?.isPlaying == true ? Double(player?.rate ?? 1) : 0
        return EditorPlaybackTimeMapping(
            hostTime: hostTime,
            presentationTime: max(0, min(rawTime - audioPresentationLatency, duration)),
            rate: effectiveRate,
            duration: duration
        )
    }

    private func rawPlaybackTime(atSystemUptime timestamp: TimeInterval) -> TimeInterval? {
        guard let player else { return nil }
        let sampledHostTime = ProcessInfo.processInfo.systemUptime
        let sampledAudioTime = player.currentTime
        guard sampledAudioTime.isFinite else { return nil }
        let rate = player.isPlaying ? Double(player.rate) : 0
        return sampledAudioTime + (timestamp - sampledHostTime) * rate
    }

    nonisolated func audioPlayerDidFinishPlaying(_ player: AVAudioPlayer, successfully flag: Bool) {
        let playerID = ObjectIdentifier(player)
        Task { @MainActor [weak self] in
            guard let self,
                  let activePlayer = self.player,
                  ObjectIdentifier(activePlayer) == playerID,
                  self.isPlaying
            else { return }
            guard flag else {
                self.suspendAudio()
                self.discardAudioPlayer()
                return
            }
            self.isPlaying = false
            self.displayLink?.isPaused = true
            self.playbackVisualFloor = nil
            self.clock.currentTime = self.duration
        }
    }
}

struct EditorPlaybackClockReader<Content: View>: View {
    @ObservedObject var clock: EditorPlaybackClock
    let content: (TimeInterval) -> Content

    init(clock: EditorPlaybackClock, @ViewBuilder content: @escaping (TimeInterval) -> Content) {
        self.clock = clock
        self.content = content
    }

    var body: some View {
        content(clock.currentTime)
    }
}

struct EditorGameplaySessionReader<Content: View>: View {
    @ObservedObject var session: SimaiGameplaySession
    let content: (SimaiGameplaySession) -> Content

    init(
        session: SimaiGameplaySession,
        @ViewBuilder content: @escaping (SimaiGameplaySession) -> Content
    ) {
        self.session = session
        self.content = content
    }

    var body: some View {
        content(session)
    }
}

@MainActor
final class EditorPreviewHitSoundController: ObservableObject {
    private var previousChartTime: TimeInterval?
    private var nextEventIndex: Int?

    func prepare(settings: SimaiPlaybackSettings) {
        SimaiHitSoundEngine.shared.prepare(
            hitVolume: settings.hitSoundVolume,
            answerVolume: settings.answerSoundVolume,
            judgementVolume: settings.judgementSoundVolume
        )
    }

    func update(
        currentTime: TimeInterval,
        chart: SimaiChart,
        settings: SimaiPlaybackSettings,
        isPlaying: Bool
    ) {
        let chartTime = currentTime + settings.audioTimingOffset
        guard isPlaying, settings.answerSoundEnabled else {
            previousChartTime = chartTime
            nextEventIndex = nil
            return
        }

        let previousTime = previousChartTime ?? max(chartTime - 0.2, -0.2)
        previousChartTime = chartTime

        // Seeking and scrubbing should reposition the scheduler without replaying
        // every note crossed by the jump.
        let elapsed = chartTime - previousTime
        guard elapsed >= 0, elapsed <= 0.25 else {
            nextEventIndex = firstEventIndex(after: chartTime, in: chart.events)
            return
        }

        var index = nextEventIndex ?? firstEventIndex(after: previousTime + 0.000_001, in: chart.events)
        var lastTriggeredTime: TimeInterval?
        while index < chart.events.count, chart.events[index].time <= chartTime + 0.002 {
            let event = chart.events[index]
            guard event.isScorable else { index += 1; continue }
            if let lastTriggeredTime, abs(event.time - lastTriggeredTime) <= 0.000_1 {
                index += 1
                continue
            }
            SimaiHitSoundEngine.shared.playAnswer(volume: settings.answerSoundVolume)
            lastTriggeredTime = event.time
            index += 1
        }
        nextEventIndex = index
    }

    private func firstEventIndex(after time: TimeInterval, in events: [SimaiNoteEvent]) -> Int {
        var lower = 0
        var upper = events.count
        while lower < upper {
            let middle = (lower + upper) / 2
            if events[middle].time > time {
                upper = middle
            } else {
                lower = middle + 1
            }
        }
        return lower
    }
}

